import{_ as i,C as r,o as n,c as h,j as e,a as o,E as d,a5 as l}from"./chunks/framework.CINlqUGR.js";const P=JSON.parse('{"title":"日志","description":"","frontmatter":{},"headers":[],"relativePath":"components/log.md","filePath":"components/log.md","lastUpdated":1787722443000}'),s={name:"components/log.md"},b={id:"日志",tabindex:"-1"};function p(u,t,g,x,m,f){const c=r("Badge"),a=r("XhDemo");return n(),h("div",null,[e("h1",b,[t[0]||(t[0]=o("日志 ",-1)),d(c,{type:"info",text:"log"}),t[1]||(t[1]=o()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#日志","aria-label":'Permalink to "日志 <Badge type="info" text="log" />"'},"​",-1))]),t[3]||(t[3]=l('<p>一块等宽排版的滚动区域，一行一条，可以自动跟到底部。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>构建输出、运行日志、命令行回显。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>展示的是结构化记录、需要筛选排序：用<a href="./table">表格</a>。</li><li>是一段代码：用<a href="./code-block">代码块</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>四层结构：<code>root</code> · <code>viewport</code> · <code>content</code> · <code>line</code>；一行写什么由作者定，组件只给身份与等宽排版。</li><li><code>rows</code> 按行数定高。</li><li>自动跟到底部；用户往上翻时停住跟随，回到底部再恢复。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>root / viewport / content / line 四层；一行写什么由作者定，组件只给身份与等宽排版</p>',10)),d(a,{src:"log/01-basic"}),t[4]||(t[4]=e("h3",{id:"按行数定高",tabindex:"-1"},[o("按行数定高 "),e("a",{class:"header-anchor",href:"#按行数定高","aria-label":'Permalink to "按行数定高"'},"​")],-1)),t[5]||(t[5]=e("p",null,"rows 定的是「看得见几行」，一行有多高归皮肤，改 --xh-log-line-height 两边一起变",-1)),d(a,{src:"log/02-rows"}),t[6]||(t[6]=e("h3",{id:"自动跟到底部",tabindex:"-1"},[o("自动跟到底部 "),e("a",{class:"header-anchor",href:"#自动跟到底部","aria-label":'Permalink to "自动跟到底部"'},"​")],-1)),t[7]||(t[7]=e("p",null,"新行进来时视口自己跟着走；往上滚一段就停住跟随，组件报出的 atBottom 与 scrollToBottom 够自己画一条回到最新",-1)),d(a,{src:"log/03-follow"}),t[8]||(t[8]=e("h3",{id:"取行中",tabindex:"-1"},[o("取行中 "),e("a",{class:"header-anchor",href:"#取行中","aria-label":'Permalink to "取行中"'},"​")],-1)),t[9]||(t[9]=e("p",null,"loading 让日志区报 aria-busy 并把指针换成忙碌态；「正在拉取」那一行是作者自己渲的",-1)),d(a,{src:"log/04-loading"}),t[10]||(t[10]=e("h3",{id:"行的样子归作者",tabindex:"-1"},[o("行的样子归作者 "),e("a",{class:"header-anchor",href:"#行的样子归作者","aria-label":'Permalink to "行的样子归作者"'},"​")],-1)),t[11]||(t[11]=e("p",null,"line 只发身份与等宽排版，级别配色、时间戳、行内标记这些都写在行里",-1)),d(a,{src:"log/05-levels"}),t[12]||(t[12]=e("h3",{id:"换成自绘滚动条",tabindex:"-1"},[o("换成自绘滚动条 "),e("a",{class:"header-anchor",href:"#换成自绘滚动条","aria-label":'Permalink to "换成自绘滚动条"'},"​")],-1)),t[13]||(t[13]=e("p",null,"视口给个 id，用滚动条的 controls 挂上去；条子浮在内容之上，不占宽度也不留空道",-1)),d(a,{src:"log/06-scrollbar"}),t[14]||(t[14]=l('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-log&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhLogContent</code> <code>XhLogLine</code> <code>XhLogRoot</code> <code>XhLogViewport</code></td></tr><tr><td>组合式函数</td><td><code>useLog</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/log.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;log&quot;</code>：<strong><code>root</code></strong> · <strong><code>viewport</code></strong> · <strong><code>content</code></strong> · <code>line</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>loading</code></td><td><code>boolean</code></td><td></td><td>行还在路上：日志区报 aria-busy，根落 data-loading。</td></tr><tr><td><code>rows</code></td><td><code>number</code></td><td></td><td>视口按多少行定高；缺省时高度由皮肤给。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;LogTranslations&gt;</code></td><td></td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>stick-change</code></td><td><code>ThreadStickChangeDetails</code></td><td>粘底状态变化；detail 为 <code>{ atBottom: boolean, sticking: boolean }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhLogRoot</code></td><td><code>default</code></td><td><code>LogRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useLog</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>rows</code></td><td><code>number | undefined</code></td><td>取整后的行数；rows 缺席或不是正数时为 undefined。</td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>atBottom</code></td><td><code>boolean</code></td><td>当前滚动位置是否落在底部阈值内。</td></tr><tr><td><code>sticking</code></td><td><code>boolean</code></td><td>新行进来时是否自动跟到底。</td></tr><tr><td><code>scrollToBottom</code></td><td><code>() =&gt; void</code></td><td>滚到底部并恢复粘附。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLineProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/practices/structural-roles/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code></td><td>焦点进入日志区</td><td>日志区自身可聚焦，方向键/PageUp/PageDown/Home/End 交给浏览器滚动，组件不接管</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>viewport</code></td><td><code>aria-busy</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>viewport</code></td><td><code>aria-label</code></td><td>props.translations?.log</td></tr><tr><td><code>viewport</code></td><td><code>role</code></td><td>&#39;log&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/log.css</code> 按部件选择：<code>[data-scope=&quot;log&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-at-bottom</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-sticking</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-log-bg</code> · <code>--xh-log-border</code> · <code>--xh-log-content-px</code> · <code>--xh-log-fg</code> · <code>--xh-log-font</code> · <code>--xh-log-font-size</code> · <code>--xh-log-line-height</code> · <code>--xh-log-radius</code> · <code>--xh-log-rows</code> · <code>--xh-log-tab-size</code></p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>行内可以用<a href="./highlight">文本高亮</a>标出关键词。</li><li>给视口一个 id，把<a href="./scrollbar">滚动条</a>的 <code>controls</code> 指过去，条子与视口平级摆在 <code>root</code> 里：它浮在内容之上，不占宽度。没挂自绘滚动条时视口自己留一条空道，原生滚动条出现与消失不会推动文字。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>用户往上翻时不要强行拉回底部，那是最恼人的行为之一。</li><li>行数很大时截断或虚拟化，别把十万行全挂上去。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>每来一行就整块重渲。</li><li>不给复制或下载全部日志的入口。</li></ul>',38))])}const k=i(s,[["render",p]]);export{P as __pageData,k as default};
